powershell -Command "
$ErrorActionPreference='SilentlyContinue'

# 3. Antigravity - find all transcript.jsonl files
$antigravPaths = @(
    'C:\Users\karma\.gemini\antigravity\brain',
    'C:\Users\karma\.gemini\antigravity-ide\brain',
    'C:\Users\karma\.antigravity\brain'
)

foreach ($p in $antigravPaths) {
    if (Test-Path $p) {
        $dirs = Get-ChildItem $p -Directory -ErrorAction SilentlyContinue
        Write-Output \"=== ANTIGRAVITY: $p ===\"
        Write-Output \"Found $($dirs.Count) brain directories\"
        foreach ($d in $dirs | Select-Object -First 20) {
            $transcript = Join-Path $d.FullName 'system_generated\logs\transcript.jsonl'
            $size = if (Test-Path $transcript) { (Get-Item $transcript).Length } else { 0 }
            $db = Join-Path $d.FullName 'conversations\*.db'
            $dbs = Get-Item $db -ErrorAction SilentlyContinue
            $dbInfo = if ($dbs) { \"DB: $($dbs.Count) files\" } else { 'No DB' }
            Write-Output \"  $($d.Name) | transcript: $size bytes | $dbInfo\"
        }
    }
}
"

powershell -Command "
$ErrorActionPreference='SilentlyContinue'

# 4. Charm Crush
$crushPaths = @(
    'C:\Users\karma\.crush',
    'C:\Users\karma\AppData\Local\crush'
)

foreach ($p in $crushPaths) {
    if (Test-Path $p) {
        Write-Output \"=== CHARM CRUSH: $p ===\"
        Get-ChildItem $p -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object {
            Write-Output \"  $($_.FullName.Replace($p, '')) | $($_.Length) bytes\"
        }
    }
}
"

powershell -Command "
$ErrorActionPreference='SilentlyContinue'

# 5. Claude Code
$claudeDir = 'C:\Users\karma\.claude'
if (Test-Path $claudeDir) {
    Write-Output '=== CLAUDE CODE ==='
    Get-ChildItem $claudeDir -File -ErrorAction SilentlyContinue | ForEach-Object {
        Write-Output \"  $($_.Name) | $($_.Length) bytes | $($_.LastWriteTime)\"
    }
    $hist = Join-Path $claudeDir 'history.jsonl'
    if (Test-Path $hist) {
        $lines = (Get-Content $hist).Count
        Write-Output \"history.jsonl: $lines lines\"
        # Read first and last few lines
        $first = Get-Content $hist -TotalCount 3
        $last = Get-Content $hist -Tail 3
        Write-Output '--- FIRST 3 LINES ---'
        $first | ForEach-Object { $_.Substring(0, [Math]::Min(200, $_.Length)) }
        Write-Output '--- LAST 3 LINES ---'
        $last | ForEach-Object { $_.Substring(0, [Math]::Min(200, $_.Length)) }
    }
    $projDir = Join-Path $claudeDir 'projects'
    if (Test-Path $projDir) {
        $projs = Get-ChildItem $projDir -Directory -ErrorAction SilentlyContinue
        Write-Output \"projects/: $($projs.Count) project dirs\"
    }
}
"
